// Regex patterns
const datePattern = /from (\d{2}-\d{2}-\d{4}) to (\d{2}-\d{2}-\d{4})/i;
const productPattern = /product\s+([a-zA-Z0-9 _-]+)/i;

// Extract
const dateMatch = text.match(datePattern);
const productMatch = text.match(productPattern);

return {
  start_date: dateMatch ? dateMatch[1] : null,
  end_date: dateMatch ? dateMatch[2] : null,
  product_name: productMatch ? productMatch[1].trim() : null
};

