/**
 * INPUT:
 *  - items = rows from Google Sheets node (each item.json is a row)
 *  - another node "Get Time Period and Product" provides:
 *      start_date (YYYY-MM-DD)
 *      end_date   (YYYY-MM-DD)
 *      product_name (e.g., "MntWines" OR "Wines")
 *
 * OUTPUT:
 *  - filtered rows with Recency, Frequency, Monetary
 */

function toNumber(v) {
  if (v === null || v === undefined || v === '') return 0;
  const cleaned = String(v).replace(/,/g, '').trim();
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : 0;
}

function parseDateSafe(v) {
  if (!v) return null;
  const d = new Date(v);
  if (!isNaN(d.getTime())) return d;

  // dd/mm/yyyy or dd-mm-yyyy
  const m = String(v).match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (m) {
    const day = Number(m[1]);
    const month = Number(m[2]) - 1;
    const year = Number(m[3]);
    const d2 = new Date(year, month, day);
    return isNaN(d2.getTime()) ? null : d2;
  }
  return null;
}

// 1) Read controls from your parameter node
const params = $items("Get Time Period and Product")[0].json;

const startDateStr = params.start_date;
const endDateStr   = params.end_date;
let productName    = params.product_name; // could be "MntWines" or "Wines"

// 2) Map product_name -> product column if user gives short names
const productMap = {
  Wines: "MntWines",
  Fruits: "MntFruits",
  Meat: "MntMeatProducts",
  Fish: "MntFishProducts",
  Sweets: "MntSweetProducts",
  Gold: "MntGoldProds",
};

const productCol = productMap[productName] || productName; // if already "MntWines", it stays

if (!startDateStr || !endDateStr) {
  throw new Error("Missing start_date or end_date from 'Get Time Period and Product' node.");
}
if (!productCol) {
  throw new Error("Missing product_name from 'Get Time Period and Product' node.");
}

// 3) Parse date range (inclusive)
const startDate = parseDateSafe(startDateStr);
const endDate = parseDateSafe(endDateStr);
if (!startDate || !endDate) {
  throw new Error('start_date/end_date must be parseable dates. Use "YYYY-MM-DD".');
}
endDate.setHours(23, 59, 59, 999);

// 4) Filter rows + compute Frequency & Monetary
const out = [];

for (const item of items) {
  const row = item.json;

  // Your sheet date column from screenshot:
  const rowDate = parseDateSafe(row.Dt_Customer);
  if (!rowDate) continue;

  // Date filter
  if (rowDate < startDate || rowDate > endDate) continue;

  // Frequency
  const frequency =
    toNumber(row.NumDealsPurchases) +
    toNumber(row.NumWebPurchases) +
    toNumber(row.NumCatalogPurchases) +
    toNumber(row.NumStorePurchases);

  // Monetary per selected product
  const monetary = toNumber(row[productCol]);

  // Optional: only keep customers who actually bought that product
  if (monetary <= 0) continue;

  out.push({
    json: {
      Dt_Customer: row.Dt_Customer,
      productCol,

      Recency: toNumber(row.Recency),
      Frequency: frequency,
      Monetary: monetary,

      // keep cluster-relevant identifiers if exist
      ID: row.ID ?? row.CustomerID ?? row.Customer_Id ?? null,
    }
  });
}

return out;

// Extract numeric values safely
function toNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function mean(arr) {
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

function stdSample(arr) {
  if (arr.length < 2) return 0;
  const m = mean(arr);
  const variance = arr.reduce((acc, x) => acc + Math.pow(x - m, 2), 0) / (arr.length - 1);
  return Math.sqrt(variance);
}

function percentile(sortedArr, p) {
  const n = sortedArr.length;
  if (n === 0) return null;
  const index = (n - 1) * p;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  if (lower === upper) return sortedArr[lower];
  return sortedArr[lower] + (sortedArr[upper] - sortedArr[lower]) * (index - lower);
}

function calculateStats(fieldName) {
  const values = items
    .map(item => toNumber(item.json[fieldName]))
    .filter(v => v !== null);

  if (values.length === 0) {
    return null;
  }

  const sorted = [...values].sort((a, b) => a - b);

  const q1 = percentile(sorted, 0.25);
  const median = percentile(sorted, 0.5);
  const q3 = percentile(sorted, 0.75);

  return {
    mean: mean(values),
    std: stdSample(values),
    q1: q1,
    median: median,
    q3: q3,
    iqr: q3 - q1,
    max: Math.max(...values),
    count: values.length
  };
}

const output = {
  Recency: calculateStats("Recency"),
  Frequency: calculateStats("Frequency"),
  Monetary: calculateStats("Monetary")
};

return [{ json: output }];

/**
 * n8n Code node (JavaScript) — Remove outliers
 * Method: IQR (Interquartile Range)
 * Behavior: removes a row if it is an outlier in ANY selected field.
 *
 * Expected numeric fields in each item.json (adjust if needed):
 *   Recency, Frequency, Monetary
 *
 * Works in "Run Once for All Items"
 */

const FIELDS = ["Recency", "Frequency", "Monetary"];

// ---------- helpers ----------
function toNumber(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

// Linear interpolation quantile (works well for IQR)
function quantile(sortedArr, q) {
  if (!sortedArr.length) return null;
  const pos = (sortedArr.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  const left = sortedArr[base];
  const right = sortedArr[Math.min(base + 1, sortedArr.length - 1)];
  return left + rest * (right - left);
}

// Build bounds for each field using IQR
function buildIqrBounds(values, k = 1.5) {
  // values should already be numeric & finite
  const sorted = values.slice().sort((a, b) => a - b);
  const q1 = quantile(sorted, 0.25);
  const q3 = quantile(sorted, 0.75);
  if (q1 === null || q3 === null) return null;

  const iqr = q3 - q1;

  // If all values are identical, iqr = 0, then no outliers (bounds == q1/q3)
  const lower = q1 - k * iqr;
  const upper = q3 + k * iqr;

  return { lower, upper, q1, q3, iqr };
}

// ---------- 1) collect numeric values per field ----------
const fieldValues = {};
for (const f of FIELDS) fieldValues[f] = [];

for (const item of items) {
  for (const f of FIELDS) {
    const n = toNumber(item.json[f]);
    if (n !== null) fieldValues[f].push(n);
  }
}

// ---------- 2) compute bounds per field ----------
const bounds = {};
for (const f of FIELDS) {
  const b = buildIqrBounds(fieldValues[f], 1.5);
  // If we can't compute (too few values), skip outlier removal for that field
  if (b) bounds[f] = b;
}

// ---------- 3) filter rows: drop if outlier in ANY field ----------
const cleanedItems = items.filter(item => {
  for (const f of FIELDS) {
    // if we couldn't compute bounds for this field, ignore it
    if (!bounds[f]) continue;

    const n = toNumber(item.json[f]);
    // if missing / non-numeric, keep the row (you can change this to drop)
    if (n === null) continue;

    if (n < bounds[f].lower || n > bounds[f].upper) {
      return false; // outlier detected
    }
  }
  return true;
});

// ---------- optional: add debug info (comment out if not needed) ----------
/*
return cleanedItems.map(it => ({
  json: {
    ...it.json,
    _outlierBounds: bounds,
  }
}));
*/

return cleanedItems;

/**
 * n8n Code node (JavaScript) — Identify which rows would be removed as outliers
 * Method: IQR (1.5 * IQR)
 * Output: returns ONLY the removed rows, with reasons (which field(s) triggered + bounds + value)
 *
 * Assumes each item.json has:
 *   Recency, Frequency, Monetary
 * and ideally a unique identifier like: ID (edit ID_FIELD if different)
 */

const FIELDS = ["Recency", "Frequency", "Monetary"];
const ID_FIELD = "ID"; // change if your unique key is different (e.g., "CustomerID")

// ---------- helpers ----------
function toNumber(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function quantile(sortedArr, q) {
  if (!sortedArr.length) return null;
  const pos = (sortedArr.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  const left = sortedArr[base];
  const right = sortedArr[Math.min(base + 1, sortedArr.length - 1)];
  return left + rest * (right - left);
}

function buildIqrBounds(values, k = 1.5) {
  const sorted = values.slice().sort((a, b) => a - b);
  const q1 = quantile(sorted, 0.25);
  const q3 = quantile(sorted, 0.75);
  if (q1 === null || q3 === null) return null;

  const iqr = q3 - q1;
  const lower = q1 - k * iqr;
  const upper = q3 + k * iqr;

  return { lower, upper, q1, q3, iqr };
}

// ---------- 1) collect numeric values per field ----------
const fieldValues = {};
for (const f of FIELDS) fieldValues[f] = [];

for (const item of items) {
  for (const f of FIELDS) {
    const n = toNumber(item.json[f]);
    if (n !== null) fieldValues[f].push(n);
  }
}

// ---------- 2) compute bounds per field ----------
const bounds = {};
for (const f of FIELDS) {
  const b = buildIqrBounds(fieldValues[f], 1.5);
  if (b) bounds[f] = b; // if null, we skip outlier detection for that field
}

// ---------- 3) find removed rows + reasons ----------
const removed = [];

for (const item of items) {
  const reasons = [];

  for (const f of FIELDS) {
    if (!bounds[f]) continue; // can't judge this field

    const n = toNumber(item.json[f]);
    if (n === null) continue; // ignore missing/non-numeric

    if (n < bounds[f].lower || n > bounds[f].upper) {
      reasons.push({
        field: f,
        value: n,
        lower: bounds[f].lower,
        upper: bounds[f].upper,
        q1: bounds[f].q1,
        q3: bounds[f].q3,
        iqr: bounds[f].iqr,
      });
    }
  }

  // Remove if ANY field flags it
  if (reasons.length > 0) {
    removed.push({
      json: {
        ...item.json,
        _outlierRemoved: true,
        _outlierId: item.json[ID_FIELD] ?? null,
        _outlierReasons: reasons,
      },
    });
  }
}

return removed;

/**
 * n8n Code node (JavaScript)
 * Elbow method for KMeans: compute WCSS for k=1..Kmax
 *
 * Input items: each item.json should contain numeric features.
 * Default fields: Recency, Frequency, Monetary
 *
 * Output: single item containing elbow_points and elbow_k_suggestion
 */

// ===== CONFIG =====
const FIELDS = ["Recency", "Frequency", "Monetary"]; // change if needed
const K_MAX = 10; // set max K to test
const MAX_ITERS = 50;
const SEED = 42;

// ===== HELPERS =====
function mulberry32(a) {
  return function () {
    let t = (a += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function toNumber(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function squaredDist(a, b) {
  let s = 0;
  for (let i = 0; i < a.length; i++) {
    const d = a[i] - b[i];
    s += d * d;
  }
  return s;
}

function meanOf(points, dim) {
  const c = new Array(dim).fill(0);
  for (const p of points) for (let i = 0; i < dim; i++) c[i] += p[i];
  for (let i = 0; i < dim; i++) c[i] /= points.length;
  return c;
}

/**
 * Simple KMeans to get WCSS (inertia).
 * Uses random init (seeded) + Lloyd's algorithm.
 */
function kmeansWCSS(X, k, maxIters, rand) {
  const n = X.length;
  const dim = X[0].length;

  // init centroids by picking k distinct random points
  const used = new Set();
  const centroids = [];
  while (centroids.length < k) {
    const idx = Math.floor(rand() * n);
    if (!used.has(idx)) {
      used.add(idx);
      centroids.push(X[idx].slice());
    }
  }

  let labels = new Array(n).fill(0);
  let changed = true;

  for (let iter = 0; iter < maxIters && changed; iter++) {
    changed = false;

    // assignment
    for (let i = 0; i < n; i++) {
      let best = 0;
      let bestD = Infinity;
      for (let c = 0; c < k; c++) {
        const d = squaredDist(X[i], centroids[c]);
        if (d < bestD) {
          bestD = d;
          best = c;
        }
      }
      if (labels[i] !== best) {
        labels[i] = best;
        changed = true;
      }
    }

    // update
    const buckets = Array.from({ length: k }, () => []);
    for (let i = 0; i < n; i++) buckets[labels[i]].push(X[i]);

    for (let c = 0; c < k; c++) {
      if (buckets[c].length === 0) {
        // re-seed empty cluster to a random point
        const idx = Math.floor(rand() * n);
        centroids[c] = X[idx].slice();
      } else {
        centroids[c] = meanOf(buckets[c], dim);
      }
    }
  }

  // compute WCSS
  let wcss = 0;
  for (let i = 0; i < n; i++) {
    wcss += squaredDist(X[i], centroids[labels[i]]);
  }
  return wcss;
}

// ===== BUILD MATRIX X =====
const X = [];
const badRows = [];

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const vec = [];
  let ok = true;

  for (const f of FIELDS) {
    const v = toNumber(row[f]);
    if (v === null) {
      ok = false;
      break;
    }
    vec.push(v);
  }

  if (ok) X.push(vec);
  else badRows.push({ index: i, json: row });
}

if (X.length < 3) {
  return [
    {
      json: {
        error: "Not enough valid rows to run elbow method.",
        required_fields: FIELDS,
        valid_rows: X.length,
        invalid_rows: badRows.length,
        invalid_examples: badRows.slice(0, 10),
      },
    },
  ];
}

const kMax = Math.min(K_MAX, X.length); // can't have k > n
const rand = mulberry32(SEED);

// ===== COMPUTE WCSS FOR EACH K =====
const points = [];
for (let k = 1; k <= kMax; k++) {
  // to reduce sensitivity, you can do multiple restarts and take min
  const RESTARTS = 3;
  let best = Infinity;
  for (let r = 0; r < RESTARTS; r++) {
    const w = kmeansWCSS(X, k, MAX_ITERS, rand);
    if (w < best) best = w;
  }
  points.push({ k, wcss: best });
}

// ===== ELBOW SUGGESTION (CURVATURE HEURISTIC) =====
// delta = wcss(k-1)-wcss(k)
// delta2 = delta(k) - delta(k+1)  (how fast improvement drops)
for (let i = 0; i < points.length; i++) {
  const prev = points[i - 1];
  const cur = points[i];
  const next = points[i + 1];

  cur.delta = prev ? prev.wcss - cur.wcss : null;
  // delta2 uses cur.delta and next.delta (needs next)
  cur.delta2 = null;
  cur.score = null;
}

for (let i = 1; i < points.length - 1; i++) {
  const cur = points[i];
  const next = points[i + 1];
  if (cur.delta != null && next.delta != null) {
    cur.delta2 = cur.delta - next.delta; // bigger => stronger elbow around k=cur.k
    // score: emphasize big curvature + still meaningful improvement
    cur.score = (cur.delta2 || 0) * (cur.delta || 0);
  }
}

// pick k with max score among 2..kMax-1
let bestK = null;
let bestScore = -Infinity;
for (let i = 1; i < points.length - 1; i++) {
  const s = points[i].score;
  if (typeof s === "number" && s > bestScore) {
    bestScore = s;
    bestK = points[i].k;
  }
}
if (bestK === null) bestK = Math.min(3, kMax);

// normalized WCSS (0..1) handy for charting
const wMin = Math.min(...points.map((p) => p.wcss));
const wMax = Math.max(...points.map((p) => p.wcss));
const wcss_normalized = points.map((p) => ({
  k: p.k,
  wcss_norm: wMax === wMin ? 0 : (p.wcss - wMin) / (wMax - wMin),
}));

return [
  {
    json: {
      fields_used: FIELDS,
      k_tested: { from: 1, to: kMax },
      elbow_k_suggestion: bestK,
      elbow_points: points,
      wcss_normalized,
      data_quality: {
        total_rows: items.length,
        valid_rows: X.length,
        invalid_rows: badRows.length,
        invalid_examples: badRows.slice(0, 10),
      },
      notes: [
        "WCSS usually decreases with higher K; elbow_k_suggestion is a heuristic (curvature-based).",
        "If your features have very different scales, run feature scaling first (e.g., z-score) before elbow.",
      ],
    },
  },
];

/**
 * n8n Code node (JavaScript)
 * Build Plotly Elbow Chart HTML + Table from elbow_points
 *
 * Expected input: items[0].json.elbow_points = [{k, wcss, delta, delta2, score}, ...]
 * Output: single item with html_elbow_chart, html_elbow_table
 */

function escHtml(s) {
  return String(s)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

const src = items?.[0]?.json || {};
const elbowPoints = Array.isArray(src.elbow_points) ? src.elbow_points : [];
const suggestedK = src.elbow_k_suggestion ?? null;

if (!elbowPoints.length) {
  return [
    {
      json: {
        error: "No elbow_points found. Make sure this node is connected after the elbow method node.",
        received_keys: Object.keys(src),
      },
    },
  ];
}

const ks = elbowPoints.map((p) => p.k);
const wcss = elbowPoints.map((p) => p.wcss);

// Build a marker highlight for suggested K
const markerSizes = ks.map((k) => (suggestedK != null && k === suggestedK ? 12 : 8));

const plotlyHtml = `
<div style="width: 100%; max-width: 900px; margin: 0 auto;">
  <h3 style="margin: 0 0 8px 0;">Elbow Method (WCSS vs K)</h3>
  <p style="margin: 0 0 12px 0; font-size: 13px;">
    Suggested K: <b>${escHtml(suggestedK ?? "N/A")}</b>
  </p>
  <div id="elbowPlot" style="width: 100%; height: 420px;"></div>
</div>

<script src="https://cdn.plot.ly/plotly-2.30.0.min.js"></script>
<script>
  (function () {
    const trace = {
      x: ${JSON.stringify(ks)},
      y: ${JSON.stringify(wcss)},
      type: "scatter",
      mode: "lines+markers",
      marker: { size: ${JSON.stringify(markerSizes)} },
      hovertemplate: "K=%{x}<br>WCSS=%{y}<extra></extra>"
    };

    const layout = {
      margin: { l: 60, r: 20, t: 20, b: 60 },
      xaxis: { title: "Number of Clusters (K)", dtick: 1 },
      yaxis: { title: "WCSS (Inertia)" },
      showlegend: false
    };

    Plotly.newPlot("elbowPlot", [trace], layout, { responsive: true });
  })();
</script>
`;

// Build HTML table
function fmtNum(v) {
  if (v === null || v === undefined) return "";
  const n = Number(v);
  if (!Number.isFinite(n)) return escHtml(String(v));
  return n.toLocaleString(undefined, { maximumFractionDigits: 4 });
}

const rowsHtml = elbowPoints
  .map((p) => {
    const isK = suggestedK != null && p.k === suggestedK;
    return `
<tr style="${isK ? "background:#f2f2f2;font-weight:700;" : ""}">
  <td style="padding:8px;border:1px solid #ddd;">${escHtml(p.k)}</td>
  <td style="padding:8px;border:1px solid #ddd;">${escHtml(fmtNum(p.wcss))}</td>
  <td style="padding:8px;border:1px solid #ddd;">${escHtml(fmtNum(p.delta))}</td>
  <td style="padding:8px;border:1px solid #ddd;">${escHtml(fmtNum(p.delta2))}</td>
  <td style="padding:8px;border:1px solid #ddd;">${escHtml(fmtNum(p.score))}</td>
</tr>`;
  })
  .join("");

const tableHtml = `
<div style="width: 100%; max-width: 900px; margin: 14px auto 0 auto;">
  <h3 style="margin: 0 0 8px 0;">Elbow Method Results Table</h3>
  <table style="border-collapse: collapse; width: 100%; font-size: 13px;">
    <thead>
      <tr>
        <th style="text-align:left;padding:8px;border:1px solid #ddd;">K</th>
        <th style="text-align:left;padding:8px;border:1px solid #ddd;">WCSS</th>
        <th style="text-align:left;padding:8px;border:1px solid #ddd;">Δ(WCSS)</th>
        <th style="text-align:left;padding:8px;border:1px solid #ddd;">Δ²</th>
        <th style="text-align:left;padding:8px;border:1px solid #ddd;">Score</th>
      </tr>
    </thead>
    <tbody>
      ${rowsHtml}
    </tbody>
  </table>
  <p style="margin:10px 0 0 0; font-size: 12px; color: #555;">
    Note: Suggested K is a heuristic (curvature-based). Validate with silhouette score or business interpretability.
  </p>
</div>
`;

return [
  {
    json: {
      elbow_k_suggestion: suggestedK,
      html_elbow_chart: plotlyHtml,
      html_elbow_table: tableHtml,
      // convenience: combine them for your Google Docs HTML pipeline
      html_elbow_section: plotlyHtml + "\n" + tableHtml,
    },
  },
];

// n8n Code node (JavaScript)
// Input items: each item.json has Recency, Frequency, Monetary
// Output: adds Recency_scaled, Frequency_scaled, Monetary_scaled

const FIELDS = ["Recency", "Frequency", "Monetary"];

function toNumber(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function mean(arr) {
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

// Sample std (ddof=1). Returns 0 if n < 2.
function stdSample(arr, m) {
  if (arr.length < 2) return 0;
  const varSum = arr.reduce((acc, x) => acc + (x - m) ** 2, 0);
  return Math.sqrt(varSum / (arr.length - 1));
}

// 1) Compute mean/std for each field
const stats = {};
for (const f of FIELDS) {
  const vals = items.map(it => toNumber(it.json[f])).filter(v => v !== null);
  const m = mean(vals);
  const s = stdSample(vals, m);
  stats[f] = { mean: m, std: s };
}

// 2) Add scaled fields
const out = items.map(it => {
  const j = { ...it.json };
  for (const f of FIELDS) {
    const x = toNumber(j[f]);
    const m = stats[f].mean;
    const s = stats[f].std;
    j[`${f}_scaled`] = (x === null) ? null : (s === 0 ? 0 : (x - m) / s);
  }
  return { json: j };
});

return out;

